@layer moduix.components {
  .root {
    grid-template-areas: 'swap';
    place-items: center;
    vertical-align: middle;

    &[data-animation='flip'] {
      perspective: var(--moduix-swap-flip-perspective, 24rem);
    }

    &[data-animation='fade'] > .indicator[data-state='open'] {
      animation: swap-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='fade'] > .indicator[data-state='closed'] {
      animation: swap-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='scale'] > .indicator[data-state='open'] {
      animation: swap-scale-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='scale'] > .indicator[data-state='closed'] {
      animation: swap-scale-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='rotate'] > .indicator[data-state='open'] {
      animation: swap-rotate-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='rotate'] > .indicator[data-state='closed'] {
      animation: swap-rotate-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='flip'] > .indicator {
      backface-visibility: hidden;
    }

    &[data-animation='flip'] > .indicator[data-state='open'] {
      animation: swap-flip-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='flip'] > .indicator[data-state='closed'] {
      animation: swap-flip-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }
  }

  .indicator {
    align-items: center;
    justify-content: center;
    color: inherit;
  }

  @media (prefers-reduced-motion: reduce) {
    .indicator[data-state] {
      animation-duration: 1ms;
      animation-delay: 0ms;
    }
  }

  @keyframes swap-enter {
    from {
      opacity: var(--moduix-swap-enter-starting-opacity, 0);
    }
  }

  @keyframes swap-exit {
    to {
      opacity: var(--moduix-swap-exit-ending-opacity, 0);
    }
  }

  @keyframes swap-scale-enter {
    from {
      opacity: var(--moduix-swap-enter-starting-opacity, 0);
      transform: scale(var(--moduix-swap-enter-starting-scale, 0.5));
    }
  }

  @keyframes swap-scale-exit {
    to {
      opacity: var(--moduix-swap-exit-ending-opacity, 0);
      transform: scale(var(--moduix-swap-exit-ending-scale, 0.5));
    }
  }

  @keyframes swap-rotate-enter {
    from {
      opacity: var(--moduix-swap-enter-starting-opacity, 0);
      transform: rotate(var(--moduix-swap-rotate-enter-starting-angle, -180deg));
    }
  }

  @keyframes swap-rotate-exit {
    to {
      opacity: var(--moduix-swap-exit-ending-opacity, 0);
      transform: rotate(var(--moduix-swap-rotate-exit-ending-angle, 180deg));
    }
  }

  @keyframes swap-flip-enter {
    from {
      opacity: var(--moduix-swap-enter-starting-opacity, 0);
      transform: rotateY(var(--moduix-swap-flip-enter-starting-angle, -180deg));
    }
  }

  @keyframes swap-flip-exit {
    to {
      opacity: var(--moduix-swap-exit-ending-opacity, 0);
      transform: rotateY(var(--moduix-swap-flip-exit-ending-angle, 180deg));
    }
  }
}

import { useSwap, useSwapContext } from '@ark-ui/vue/swap';
import Swap from './Swap.vue';
import SwapIndicator from './SwapIndicator.vue';
import SwapRootProvider from './SwapRootProvider.vue';

export { Swap, SwapIndicator, SwapRootProvider, useSwap, useSwapContext };
export type { SwapAnimation } from './Swap.vue';
export type {
  SwapIndicatorProps,
  SwapRootProps,
  SwapRootProviderProps,
  UseSwapContext,
  UseSwapProps,
  UseSwapReturn,
} from '@ark-ui/vue/swap';
